package genhelper_test

import (
	"encoding/json/jsontext"
	"encoding/json/v2"
	"errors"
	"go/ast"
	"go/parser"
	"go/token"
	"strings"
	"testing"
	"time"

	"gotest.tools/v3/assert"

	"github.com/ngicks/kama/kamalib/pkg/genhelper"
)

func TestGeneratedComment(t *testing.T) {
	assert.Equal(
		t,
		genhelper.GeneratedComment("example.com/gen"),
		"// Code generated by example.com/gen. DO NOT EDIT.",
	)
}

func TestGeneratorParamsComment(t *testing.T) {
	for _, tc := range []struct {
		name string
		g    genhelper.GeneratorParams
		want string
	}{
		{
			name: "name only",
			g:    genhelper.GeneratorParams{Name: "example.com/gen"},
			want: "// Code generated by example.com/gen. DO NOT EDIT.",
		},
		{
			name: "argv",
			g: genhelper.GeneratorParams{
				Name: "example.com/gen",
				Argv: []string{"-type", "T", "an argument", "", "line\nbreak"},
			},
			want: "// Code generated by example.com/gen. DO NOT EDIT.\n" +
				"// argv: -type T \"an argument\" \"\" \"line\\nbreak\"",
		},
		{
			name: "params are sorted and encoded as JSON",
			g: genhelper.GeneratorParams{
				Name: "example.com/gen",
				Params: map[string]any{
					"tags":    []string{"a", "b"},
					"depth":   3,
					"output":  "line\nbreak",
					"a key":   true,
					"nested":  map[string]any{"z": 1, "a": nil},
					"comment": "*/ // text",
				},
			},
			want: "// Code generated by example.com/gen. DO NOT EDIT.\n" +
				"// params:\n" +
				"//\t\"a key\": true\n" +
				"//\tcomment: \"*/ // text\"\n" +
				"//\tdepth: 3\n" +
				"//\tnested: {\"a\":null,\"z\":1}\n" +
				"//\toutput: \"line\\nbreak\"\n" +
				"//\ttags: [\"a\",\"b\"]",
		},
		{
			name: "params leave HTML characters unescaped",
			g: genhelper.GeneratorParams{
				Name:   "example.com/gen",
				Params: map[string]any{"html": "<a> & <b>"},
			},
			want: "// Code generated by example.com/gen. DO NOT EDIT.\n" +
				"// params:\n" +
				"//\thtml: \"<a> & <b>\"",
		},
		{
			name: "params sort keys of nested maps",
			g: genhelper.GeneratorParams{
				Name: "example.com/gen",
				Params: map[string]any{
					"nested": map[string]any{
						"m": 1,
						"c": 2,
						"x": map[string]int{"k": 1, "b": 2, "t": 3, "a": 4},
						"a": 3,
						"q": 4,
						"f": 5,
					},
				},
			},
			want: "// Code generated by example.com/gen. DO NOT EDIT.\n" +
				"// params:\n" +
				"//\tnested: {\"a\":3,\"c\":2,\"f\":5,\"m\":1,\"q\":4," +
				"\"x\":{\"a\":4,\"b\":2,\"k\":1,\"t\":3}}",
		},
		{
			name: "params print nil",
			g: genhelper.GeneratorParams{
				Name: "example.com/gen",
				Params: map[string]any{
					"untyped": nil,
					"slice":   []string(nil),
					"map":     map[string]int(nil),
				},
			},
			want: "// Code generated by example.com/gen. DO NOT EDIT.\n" +
				"// params:\n" +
				"//\tmap: {}\n" +
				"//\tslice: []\n" +
				"//\tuntyped: null",
		},
		{
			name: "argv and params",
			g: genhelper.GeneratorParams{
				Name:   "example.com/gen",
				Argv:   []string{"./..."},
				Params: map[string]any{"version": "v1"},
			},
			want: "// Code generated by example.com/gen. DO NOT EDIT.\n" +
				"// argv: ./...\n" +
				"// params:\n" +
				"//\tversion: \"v1\"",
		},
		{
			name: "generated in UTC",
			g: genhelper.GeneratorParams{
				Name: "example.com/gen",
				Generated: time.Date(
					2026, 11, 4, 19, 12, 33, 999_000_000, time.FixedZone("JST", 9*60*60),
				),
			},
			want: "// Code generated by example.com/gen. DO NOT EDIT.\n" +
				"// generated: 2026-11-04T10:12:33Z",
		},
		{
			name: "generated after params",
			g: genhelper.GeneratorParams{
				Name:      "example.com/gen",
				Argv:      []string{"./..."},
				Params:    map[string]any{"version": "v1"},
				Generated: time.Date(2030, 1, 2, 3, 4, 5, 0, time.UTC),
			},
			want: "// Code generated by example.com/gen. DO NOT EDIT.\n" +
				"// argv: ./...\n" +
				"// params:\n" +
				"//\tversion: \"v1\"\n" +
				"// generated: 2030-01-02T03:04:05Z",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, err := tc.g.Comment()
			assert.NilError(t, err)
			assert.Equal(t, got, tc.want)
		})
	}
}

func TestGeneratorParamsCommentError(t *testing.T) {
	t.Run("unsupported type", func(t *testing.T) {
		_, err := genhelper.GeneratorParams{
			Name:   "example.com/gen",
			Params: map[string]any{"ch": make(chan int)},
		}.Comment()

		var semantic *json.SemanticError
		assert.Assert(t, errors.As(err, &semantic), "%v", err)
	})

	t.Run("invalid UTF-8", func(t *testing.T) {
		_, err := genhelper.GeneratorParams{
			Name:   "example.com/gen",
			Params: map[string]any{"s": "\xff"},
		}.Comment()

		var syntactic *jsontext.SyntacticError
		assert.Assert(t, errors.As(err, &syntactic), "%v", err)
	})
}

func TestGeneratorParamsHeader(t *testing.T) {
	comment, err := genhelper.GeneratorParams{
		Name:      "example.com/gen",
		Argv:      []string{"-type", "T"},
		Params:    map[string]any{"version": "v1"},
		Generated: time.Date(2030, 1, 2, 3, 4, 5, 0, time.UTC),
	}.Comment()
	assert.NilError(t, err)

	type ctx = genhelper.BaseContext

	_, b, err := genhelper.WrapFile[ctx]([]string{comment, "//go:build linux"}, "p").
		Render(genhelper.NewBaseContext(genhelper.NewScope(), nil), []byte("var x = 1\n"))
	assert.NilError(t, err)
	assert.Equal(t, string(b), `// Code generated by example.com/gen. DO NOT EDIT.
// argv: -type T
// params:
//	version: "v1"
// generated: 2030-01-02T03:04:05Z

//go:build linux

package p

var x = 1
`)

	f, err := parser.ParseFile(token.NewFileSet(), "", b, parser.ParseComments)
	assert.NilError(t, err)
	assert.Assert(t, ast.IsGenerated(f))
}

func TestSameExceptGenerated(t *testing.T) {
	const (
		a = "// x\n// generated: 2026-11-04T10:12:33Z\n\npackage x\n\n// generated: a\n"
		b = "// x\n// generated: 2030-01-02T03:04:05Z\n\npackage x\n\n// generated: a\n"
		c = "// x\n// generated: 2026-11-04T10:12:33Z\n\npackage x\n\n// generated: b\n"
		d = "// x\n\npackage x\n\n// generated: a\n"
	)
	assert.Assert(t, genhelper.SameExceptGenerated([]byte(a), []byte(b)))
	assert.Assert(t, !genhelper.SameExceptGenerated([]byte(a), []byte(c)))
	assert.Assert(t, genhelper.SameExceptGenerated([]byte(a), []byte(d)))
	assert.Assert(
		t,
		!genhelper.SameExceptGenerated([]byte(a), []byte(strings.Replace(a, "// x", "// y", 1))),
	)
}
